import {reviewIsCurrent} from './core.mjs';
import {proofIsCurrent} from './operations.mjs';
import {historicalProofAt} from './focus-model.mjs';
import {agentDecisionBrief} from './focus-agent-brief.mjs';
import {replayAgents} from './focus-case-replay.mjs';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=value=>value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString():'Not checked';
const money=cents=>Number.isFinite(Number(cents))?`${(Number(cents)/100).toFixed(2)}`:'—';
const pair=(label,value)=>`<div><dt>${esc(label)}</dt><dd>${esc(value??'—')}</dd></div>`;
const sourceName={payment:'Payment capture',order:'Saved order',event:'Event trail',store:'Course access'};

// Each first-look fact opens the record and comparison that produced its label.
export function purchaseFactsMarkup(s,{uncertain=false}={}){
 const capture=s.evidenceAvailable===false?null:s.capture,order=s.order||{},entitlement=s.entitlement||{};
 const paymentAvailable=!!capture&&s.sources?.payment?.status!=='unavailable'&&!uncertain;
 const paymentOk=paymentAvailable&&capture.status==='COMPLETED';
 const matchRows=[['Order',capture?.orderId,order.id],['Learner',capture?.userId,order.userId],['Course',capture?.courseId,order.courseId],['Amount',capture?money(capture.amount):null,money(order.amount)],['Currency',capture?.currency,order.currency]];
 const exact=paymentOk&&matchRows.every(([,observed,expected])=>observed===expected);
 const accessAvailable=s.sources?.access?.status!=='unavailable'&&!uncertain;
 const accessMatches=accessAvailable&&entitlement.active===true&&entitlement.userId===order.userId&&entitlement.courseId===order.courseId&&entitlement.captureId===capture?.id;
 const sample=capture?.source!=='paypal-sandbox';
 const paymentTime=s.sources?.payment?.checkedAt||(sample?s.paidAt:null);
 const accessTime=s.sources?.access?.checkedAt||null;
 const matchStatus=!paymentAvailable?'Current capture unavailable':exact?'Exact fields agree':'Review required';
 const paymentStatus=paymentOk?'Completed':paymentAvailable?capture.status||'Not completed':'Not confirmed';
 const accessStatus=!accessAvailable?'Current status unavailable':accessMatches?'Matching entitlement':entitlement.active?'Entitlement needs review':'Missing or unconfirmed';
 const fact=(key,label,status,caption,body)=>`<details class="case-fact case-fact-${key}" id="case-fact-${key}"><summary><span class="case-fact-top"><span class="case-first-look-label">${label}</span><span class="case-fact-chevron" aria-hidden="true"></span></span><strong>${esc(status)}</strong><small>${esc(caption)}</small><span class="case-fact-open">Inspect source & match</span></summary><div class="case-fact-record">${body}</div></details>`;
 const payment=fact('payment','Payment',paymentStatus,sample?'Illustrative sample record':'PayPal sandbox capture',`<div class="case-fact-record-title"><strong>Payment capture</strong><span>${sample?'Sample record':'PayPal sandbox'}</span></div><dl>${pair('Capture ID',capture?.id)}${pair('Status',capture?.status)}${pair('Order reference',capture?.orderId)}${pair('Amount',capture?`${money(capture.amount)} ${capture.currency}`:null)}${pair('Checked',paymentTime?when(paymentTime):'No current payment check recorded')}</dl><p class="case-fact-result">${paymentOk?'Match result: completed capture recorded. The order fields are compared separately.':'Match result: a completed, readable capture is required before access can change.'}</p>`);
 const comparison=fact('match','Purchase match',matchStatus,'Capture compared with saved order',`<div class="case-fact-record-title"><strong>Exact purchase comparison</strong><span>Payment capture ↔ saved order</span></div><div class="case-match-table" role="table" aria-label="Capture and saved order comparison"><div role="row" class="case-match-head"><span role="columnheader">Field</span><span role="columnheader">Capture</span><span role="columnheader">Order</span><span role="columnheader">Result</span></div>${matchRows.map(([label,observed,expected])=>`<div role="row"><span role="cell">${esc(label)}</span><span role="cell">${esc(observed??'Unavailable')}</span><span role="cell">${esc(expected??'Unavailable')}</span><span role="cell">${capture?observed===expected?'Matches':'Differs':'Unavailable'}</span></div>`).join('')}</div><p class="case-fact-result">${exact?'Match result: all five purchase fields agree with a completed capture.':'Match result: at least one required field or the completed capture is unavailable or conflicting.'}</p><small>Payment last checked: ${esc(paymentTime?when(paymentTime):'No current check recorded')}</small>`);
 const access=fact('access','Purchased access',accessStatus,s.proof?.passed&&proofIsCurrent(s)?'Protected lesson verified':'Protected lesson not yet proven',`<div class="case-fact-record-title"><strong>Course access record</strong><span>${esc(s.sources?.access?.system||'Case access record')}</span></div><dl>${pair('Learner',entitlement.userId)}${pair('Course',entitlement.courseId)}${pair('Entitlement',entitlement.active?'Active':'Inactive')}${pair('Capture reference',entitlement.captureId||'None')}${pair('Checked',accessTime?when(accessTime):'No current access check recorded')}</dl><p class="case-fact-result">${accessMatches?'Match result: active access belongs to this learner, course, and capture.':accessAvailable?'Match result: matching active access is not established.':'Match result: the access source is unavailable; absence cannot be inferred.'}</p>${s.proof?`<small>Protected lesson: ${s.proof.checks?.find(item=>item.label==='Purchased lesson content retrieved')?.ok&&proofIsCurrent(s)?'Passed':'Not currently verified'} · ${esc(when(s.proof.at))}</small>`:''}`);
 return payment+comparison+access;
}

export function agentConsensusMarkup(s,{uncertain=false}={}){
 if(!s.review)return '';
 const agents=replayAgents(s),brief=agentDecisionBrief(s,{uncertain}),historical=s.writes>0&&!!s.approval,current=reviewIsCurrent(s)&&!uncertain,verified=!uncertain&&proofIsCurrent(s)&&s.evidenceAvailable!==false&&!Object.values(s.sources||{}).some(source=>source?.status==='unavailable');
 const unresolved=(s.review.objections||[]).filter(item=>item.status==='open');
 const state=historical?'Decision-time review':current?'Current review':'Review out of date';
 const agreement=agents.length===4?unresolved.length?`${4-unresolved.length} findings recorded · ${unresolved.length} open challenge${unresolved.length===1?'':'s'}`:'Four findings recorded · no open challenge':`${agents.length} of 4 findings available`;
 const sourceMarkup=item=>item.sources.length?item.sources.map(source=>`<details class="case-agent-source"><summary>${esc(sourceName[source]||source)} · saved evidence</summary><pre>${esc(JSON.stringify(s.review.snapshot?.[source]??null,null,2))}</pre></details>`).join(''):'<p>No saved citation available for this finding.</p>';
 return `<section class="case-agent-consensus" id="case-agent-consensus" aria-label="Specialist review summary"><div class="case-agent-consensus-head"><div><span class="eyebrow">${s.review.mode==='model'?'AI SPECIALISTS':'SCRIPTED SAMPLE SPECIALISTS'} · ${esc(state)}</span><h2>${esc(verified?'Specialists’ decision is recorded. Access is verified.':brief?.title||'Review recorded')}</h2></div><span class="case-agent-consensus-count">${esc(agreement)}</span></div><div class="case-agent-consensus-brief"><p><strong>${verified?'Decision-time action':'Recommended action'}</strong> ${esc(verified?'The saved review supported the approved correction. Fresh payment, entitlement, and lesson checks now prove the technical outcome.':brief?.next||s.review.proposal)}</p><p><strong>Still uncertain</strong> ${esc(verified?'The buyer has not separately confirmed that the lesson opens on their device.':unresolved[0]?.question||brief?.challenge||s.review.unknown)}</p></div><div class="case-agent-consensus-list">${agents.map(item=>`<details class="case-agent-compact"><summary><span class="case-agent-avatar" aria-hidden="true">${esc(item.name.slice(0,1))}</span><span><strong>${esc(item.name)}</strong><small>${esc(item.role)}</small></span><span class="case-agent-confidence">${esc(item.confidence==='Moderate'?'Conditional':item.confidence)}</span></summary><div class="case-agent-compact-body"><p><strong>Finding</strong> ${esc(item.summary)}</p><p><strong>Limit</strong> ${esc(item.unknown||'The evidence does not establish every cause.')}</p><p class="case-agent-confidence-note">Evidence confidence ${esc(item.scope)}: ${esc(item.reason)} This is a qualitative assessment of saved records, not a model probability.</p><div class="case-agent-citations"><strong>Cited records</strong>${sourceMarkup(item)}</div></div></details>`).join('')}</div>${agents.length===0?'<p class="case-agent-empty">Saved findings are unavailable. Run a fresh investigation.</p>':''}</section>`;
}

export function outcomeProofMarkup(s,{uncertain=false}={}){
 if(!s.approval&&!s.writes&&!s.proof)return '';
 const verified=!uncertain&&!s.paymentHold&&proofIsCurrent(s)&&s.evidenceAvailable!==false&&!Object.values(s.sources||{}).some(source=>source?.status==='unavailable');
 const completedAt=historicalProofAt(s);
 const paymentCheck=s.proof?.checks?.find(item=>item.label==='Fresh payment record');
 const accessCheck=s.proof?.checks?.find(item=>item.label==='Access belongs to this learner and course');
 const lessonCheck=s.proof?.checks?.find(item=>item.label==='Purchased lesson content retrieved');
 const sample=s.capture?.source!=='paypal-sandbox';
 const stage=(number,title,status,detail,record)=>`<details class="case-outcome-stage"><summary><span class="case-outcome-number" aria-hidden="true">${number}</span><span><strong>${title}</strong><small>${esc(status)}</small></span></summary><div class="case-outcome-record">${record}<p>${esc(detail)}</p></div></details>`;
 const payment=stage('01','Payment',verified&&paymentCheck?.ok?'Fresh check passed':'Fresh check pending','The completed capture must still match this purchase.',`<dl>${pair('Source',sample?'Sample payment':'PayPal sandbox')}${pair('Capture',s.capture?.id)}${pair('Check',paymentCheck?.ok?'Passed':paymentCheck?'Failed':'Not run')}${pair('Checked',s.proof?.at?when(s.proof.at):'Not checked')}</dl>`);
 const grant=stage('02',s.writes||s.approval?'Access grant':'Access record',s.writes===1?'One write recorded':s.writes>1?`${s.writes} writes recorded`:s.approval?'Approved · not applied':verified?'Already active · no grant needed':'Current access unconfirmed','An approved write is separate from a passing entitlement check.',`<dl>${pair('Authorization',s.approval?.mode==='policy'?'Merchant policy':s.approval?'Merchant approval':'No grant needed')}${pair('Approved',s.approval?.at?when(s.approval.at):'Not applicable')}${pair('Writes',s.writes)}${pair('Entitlement check',accessCheck?.ok?'Passed':accessCheck?'Failed':'Not run')}</dl>`);
 const lesson=stage('03','Lesson proof',verified&&lessonCheck?.ok?'Protected lesson opened':lessonCheck?'Check did not pass':'Not yet verified','Technical lesson proof does not mean the buyer has confirmed access on their own device.',`<dl>${pair('Content',s.proof?.resource?.contentId||'Not recorded')}${pair('Check',lessonCheck?.ok?'Passed':lessonCheck?'Failed':'Not run')}${pair('Checked',s.proof?.at?when(s.proof.at):'Not checked')}${pair('Method',s.proof?.transport||'Not recorded')}</dl>`);
 return `<section class="case-outcome-proof" aria-label="Recovery outcome proof"><span class="eyebrow">${sample?'ILLUSTRATIVE SAMPLE':'PAYPAL SANDBOX'} · OUTCOME</span><h3>${verified?'Recovery verified · lesson opened':s.paymentHold?'Payment changed · recovery on hold':completedAt&&!uncertain?'Previously verified · recheck due':s.writes?'Access changed; verification pending':s.approval?'Approved; access change pending':'Technical verification needs refresh'}</h3><p>${verified?'Payment, matching entitlement, and protected lesson checks passed. Buyer confirmation remains separate.':s.paymentHold?'The payment changed. Review current payment evidence before any further access change.':completedAt&&!uncertain?`A recovery passed on ${esc(when(completedAt))}. This is a historical result; current access needs a fresh check.`:'Follow each recorded check. The case stays open until fresh verification passes.'}</p><div class="case-outcome-track">${payment}${grant}${lesson}</div></section>`;
}
